"""Random arrays and k values, including k at both ends of its range."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(1, 20)
    values = [rng.randint(-50, 50) for _ in range(n)]
    k = rng.choice([1, n, rng.randint(1, n)])
    lines = ["%d %d" % (n, k)] + [str(v) for v in values]
    return {"name": "%d values, k=%d #%d" % (n, k, index),
            "stdin": " ".join(lines) + "\n"}
